package com.hbm.entity.mob.ufo;
import net.minecraft.core.*;import net.minecraft.network.syncher.*;import net.minecraft.util.Mth;import net.minecraft.world.Difficulty;import net.minecraft.world.effect.MobEffects;import net.minecraft.world.entity.*;import net.minecraft.world.entity.monster.Enemy;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.Level;import net.minecraft.world.level.levelgen.Heightmap;import net.minecraft.world.phys.Vec3;
/** Actual source abstract helper, not a registered mob and not EntityUFO's superclass. Cooldowns deliberately are not auto-decremented: source delegates that to its eventual subclass. */
public abstract class EntityUFOBase extends FlyingMob implements Enemy {
 private static final EntityDataAccessor<Integer> X=SynchedEntityData.defineId(EntityUFOBase.class,EntityDataSerializers.INT),Y=SynchedEntityData.defineId(EntityUFOBase.class,EntityDataSerializers.INT),Z=SynchedEntityData.defineId(EntityUFOBase.class,EntityDataSerializers.INT);protected int scanCooldown,courseChangeCooldown;protected Entity target;
 protected EntityUFOBase(EntityType<? extends EntityUFOBase> type,Level level){super(type,level);}@Override protected void registerGoals(){}@Override protected void defineSynchedData(SynchedEntityData.Builder b){super.defineSynchedData(b);b.define(X,0);b.define(Y,0);b.define(Z,0);}
 @Override protected void customServerAiStep(){if(level().getDifficulty()==Difficulty.PEACEFUL){discard();return;}setDeltaMovement(Vec3.ZERO);if(target!=null&&!target.isAlive())target=null;scanForTarget();if(courseChangeCooldown<=0)setCourse();}
 protected boolean canAttackClass(Class<?> type){return true;}protected int getScanRange(){return 50;}protected int getScanDelay(){return 100;}
 protected void scanForTarget(){int range=getScanRange();if(scanCooldown<=0){target=null;for(var e:level().getEntities(this,getBoundingBox().inflate(range,range/2,range))){if(!e.isAlive()||!canAttackClass(e.getClass()))continue;if(e instanceof Player p){if(p.getAbilities().instabuild||p.isSpectator()||p.hasEffect(MobEffects.INVISIBILITY))continue;if(target==null||distanceToSqr(e)<distanceToSqr(target))target=e;}}scanCooldown=getScanDelay();}}
 protected boolean isCourseTraversable(double ignoredX,double ignoredY,double ignoredZ,double length){double x=(waypointX()-getX())/length,y=(waypointY()-getY())/length,z=(waypointZ()-getZ())/length;var box=getBoundingBox();for(int i=1;i<length;i++){box=box.move(x,y,z);if(!level().noCollision(this,box))return false;}return true;}
 protected void approachPosition(double speed){var delta=new Vec3(waypointX()-getX(),waypointY()-getY(),waypointZ()-getZ());double length=delta.length();if(length>5){if(isCourseTraversable(waypointX(),waypointY(),waypointZ(),length))setDeltaMovement(delta.scale(speed/length));else courseChangeCooldown=0;}}
 protected void setCourse(){if(target!=null){setCourseForTaget();courseChangeCooldown=20+random.nextInt(20);}else{setCourseWithoutTaget();courseChangeCooldown=60+random.nextInt(20);}}
 protected void setCourseForTaget(){var delta=new Vec3(getX()-target.getX(),0,getZ()-target.getZ()).yRot((float)Math.PI*2*random.nextFloat());double length=delta.length(),overshoot=10+random.nextDouble()*10;int x=Mth.floor(target.getX()-delta.x/length*overshoot),z=Mth.floor(target.getZ()-delta.z/length*overshoot);setWaypoint(x,Math.max(surface(x,z),(int)target.getY())+targetHeightOffset(),z);}
 protected int targetHeightOffset(){return 2+random.nextInt(2);}protected int wanderHeightOffset(){return 2+random.nextInt(3);}protected void setCourseWithoutTaget(){int x=Mth.floor(getX()+random.nextGaussian()*5),z=Mth.floor(getZ()+random.nextGaussian()*5);setWaypoint(x,surface(x,z)+wanderHeightOffset(),z);}private int surface(int x,int z){int top=level().getHeight(Heightmap.Types.WORLD_SURFACE,x,z);for(int y=top-1;y>=level().getMinBuildHeight();y--){var pos=new BlockPos(x,y,z);if(level().getBlockState(pos).getLightBlock(level(),pos)>0)return y+1;}return level().getMinBuildHeight();}
 public void setWaypoint(int x,int y,int z){entityData.set(X,x);entityData.set(Y,y);entityData.set(Z,z);}public int waypointX(){return entityData.get(X);}public int waypointY(){return entityData.get(Y);}public int waypointZ(){return entityData.get(Z);}
}
